import os
try:
 from bs4 import BeautifulSoup
except Exception as e:
 print('NO_BS4',e); raise SystemExit
s=BeautifulSoup(open(os.environ['HOME_FILE']).read(),'html.parser')
for i,t in enumerate(s.find_all('table')):
 print('TABLE',i)
 for tr in t.find_all('tr'):
  cells=[' '.join(c.get_text(' ',strip=True).split()) for c in tr.find_all(['th','td'])]
  if cells: print('\\t'.join(cells))
